pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // newOwner is fuzzed; the fuzzer will try address(0) and non-zero addresses
        // c is already the owner (constructor transfers ownership to address(this) in setUp)
        vm.prank(address(this));
        bool ok = true;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(c.owner(), newOwner, "owner must equal newOwner on success");
        }
    }
}

